#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    size_t result = books.size();

    #pragma omp parallel
    {
        size_t local_last = books.size();

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(books.size()); ++i) {
            if (books[static_cast<size_t>(i)].pages < 100) {
                local_last = static_cast<size_t>(i);
            }
        }

        #pragma omp critical
        {
            if (local_last != books.size() &&
                (result == books.size() || local_last > result)) {
                result = local_last;
            }
        }
    }

    return result;
}
